import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")
TASK_ID_RE = re.compile(r"\d+")


def _valid_pesel(pesel: str) -> bool:
    """Validate the length, contents, and check digit of a PESEL."""
    if len(pesel) != 11 or not pesel.isdigit():
        return False
    weights = (1, 3, 7, 9, 1, 3, 7, 9, 1, 3)
    check_digit = (10 - sum(int(d) * w for d, w in zip(pesel, weights)) % 10) % 10
    return check_digit == int(pesel[-1])


def _first_weekday(year: int, month: int, weekday: int) -> date:
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def _previous_month(year: int, month: int) -> tuple[int, int]:
    return (year - 1, 12) if month == 1 else (year, month - 1)


def _billing_month(day: date, start_weekday: int) -> tuple[int, int]:
    """Return the month whose first start_weekday begins this billing period."""
    start = _first_weekday(day.year, day.month, start_weekday)
    return (day.year, day.month) if day >= start else _previous_month(day.year, day.month)


def _read_employees() -> tuple[list[str], dict[str, Decimal]]:
    order: list[str] = []
    rates: dict[str, Decimal] = {}
    conflicts: set[str] = set()

    with (DATASET / "employees.csv").open(newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            pesel = row["PESEL"].strip()
            try:
                rate = Decimal(row["hourly_rate"])
                date.fromisoformat(row["date_of_birth"])
                date.fromisoformat(row["hire_date"])
            except (InvalidOperation, ValueError):
                continue
            if not _valid_pesel(pesel) or rate <= 0:
                continue
            if pesel in rates and rates[pesel] != rate:
                conflicts.add(pesel)
                continue
            if pesel not in rates:
                order.append(pesel)
                rates[pesel] = rate

    for pesel in conflicts:
        rates.pop(pesel, None)
        if pesel in order:
            order.remove(pesel)
    return order, rates


def _read_task_pay() -> dict[int, Decimal]:
    task_pay: dict[int, Decimal] = {}
    conflicts: set[int] = set()
    with (DATASET / "tasks.csv").open(newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            try:
                task_id = int(row["task_id"])
                pay = Decimal(row["pay_per_completion"])
            except (InvalidOperation, TypeError, ValueError):
                continue
            if task_id <= 0 or pay < 0:
                continue
            if task_id in task_pay and task_pay[task_id] != pay:
                conflicts.add(task_id)
            else:
                task_pay[task_id] = pay
    for task_id in conflicts:
        task_pay.pop(task_id, None)
    return task_pay


def answer() -> dict[str, list[int]]:
    employee_order, hourly_rates = _read_employees()
    task_pay = _read_task_pay()

    # Read once so the earliest valid record can supply the common weekday.
    raw_rows: list[dict[str, str]] = []
    with (DATASET / "timesheet.csv").open(newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        fields = reader.fieldnames or []
        seen: set[tuple[str, ...]] = set()
        for row in reader:
            # The ID differs in injected duplicates, so it is not part of the
            # logical-record identity.
            signature = tuple(row.get(field, "") for field in fields if field != "id")
            if signature in seen:
                continue
            seen.add(signature)
            raw_rows.append(row)

    parsed_dates: list[date] = []
    for row in raw_rows:
        try:
            parsed_dates.append(date.fromisoformat(row["date"]))
        except ValueError:
            pass
    if not parsed_dates:
        return {pesel: [] for pesel in employee_order}
    start_weekday = min(parsed_dates).weekday()

    totals: defaultdict[tuple[str, tuple[int, int]], Decimal] = defaultdict(Decimal)
    billing_months: set[tuple[int, int]] = set()

    for row in raw_rows:
        pesel = row["employee_id"].strip()
        if pesel not in hourly_rates:
            # Unknown/corrupt IDs cannot safely be assigned to an employee.
            continue
        try:
            work_date = date.fromisoformat(row["date"])
            hours = Decimal(row["hours_worked"])
        except (InvalidOperation, ValueError):
            continue
        if not hours.is_finite() or hours < 0 or hours > 24:
            continue

        month = _billing_month(work_date, start_weekday)
        billing_months.add(month)

        # Extracting integers also repairs a missing opening/closing bracket.
        # IDs absent from the authoritative task table have no recoverable pay.
        bonus = sum(
            (task_pay.get(int(task_id), Decimal(0))
             for task_id in TASK_ID_RE.findall(row["performed_tasks"])),
            Decimal(0),
        )
        totals[(pesel, month)] += hours * hourly_rates[pesel] + bonus

    months = sorted(billing_months)
    result: dict[str, list[int]] = {}
    for pesel in employee_order:
        result[pesel] = [
            int(totals[(pesel, month)].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for month in months
        ]
    return result


if __name__ == "__main__":
    with Path("/app/answer.json").open("w", encoding="utf-8") as f:
        json.dump(answer(), f, default=list)
